def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    candidates = []

    # A pair of matching cells, no more than four spaces apart,
    # establishes a periodic line in its row or column.
    for r in range(h):
        for a in range(w):
            if src[r][a] == 0:
                continue
            for b in range(a + 1, min(w, a + 5)):
                if src[r][b] == src[r][a]:
                    candidates.append(("H", r, a, b, src[r][a]))

    for c in range(w):
        for a in range(h):
            if src[a][c] == 0:
                continue
            for b in range(a + 1, min(h, a + 5)):
                if src[b][c] == src[a][c]:
                    candidates.append(("V", c, a, b, src[a][c]))

    # Track cells that already participate in a candidate line in each direction.
    h_endpoints = set()
    v_endpoints = set()
    for orient, fixed, a, b, color in candidates:
        if orient == "H":
            h_endpoints.add((fixed, a))
            h_endpoints.add((fixed, b))
        else:
            v_endpoints.add((a, fixed))
            v_endpoints.add((b, fixed))

    proposals = []
    for orient, fixed, a, b, color in candidates:
        # Ignore an ambiguous pair when both endpoints also form vertical /
        # horizontal patterns in the other direction.
        if orient == "H":
            if (fixed, a) in v_endpoints and (fixed, b) in v_endpoints:
                continue
            length = w
            values = src[fixed]
        else:
            if (a, fixed) in h_endpoints and (b, fixed) in h_endpoints:
                continue
            length = h
            values = [src[r][fixed] for r in range(h)]

        step = b - a
        lattice = list(range(a % step, length, step))

        # A different color on the same periodic lattice determines the
        # color of the extended line; otherwise retain the paired color.
        markers = [values[p] for p in lattice
                   if values[p] != 0 and values[p] != color]
        line_color = markers[0] if markers else color
        proposals.append((orient, fixed, a % step, step, line_color))

    for orient, fixed, phase, step, color in proposals:
        length = w if orient == "H" else h
        for p in range(phase, length, step):
            if orient == "H":
                out[fixed][p] = color
            else:
                out[p][fixed] = color

    return out
