def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    horizontal = []
    vertical = []

    # A line is seeded by a color appearing exactly twice on that row/column.
    for r in range(h):
        positions = {}
        for c, color in enumerate(src[r]):
            if color:
                positions.setdefault(color, []).append(c)
        for color, ps in positions.items():
            if len(ps) == 2:
                horizontal.append((r, ps[0], ps[1], color))

    for c in range(w):
        positions = {}
        for r in range(h):
            color = src[r][c]
            if color:
                positions.setdefault(color, []).append(r)
        for color, ps in positions.items():
            if len(ps) == 2:
                vertical.append((c, ps[0], ps[1], color))

    # Use the orientation containing the greater number of repeated pairs.
    use_horizontal = len(horizontal) > len(vertical)
    candidates = horizontal if use_horizontal else vertical

    for fixed, a, b, color in candidates:
        step = b - a
        length = w if use_horizontal else h
        values = src[fixed] if use_horizontal else [src[r][fixed] for r in range(h)]

        left = a
        right = b
        blocker_colors = []

        p = a - step
        while p >= 0:
            if values[p] != 0:
                blocker_colors.append(values[p])
                left = p
                break
            left = p
            p -= step

        p = b + step
        while p < length:
            if values[p] != 0:
                blocker_colors.append(values[p])
                right = p
                break
            right = p
            p += step

        line_color = blocker_colors[0] if blocker_colors else color
        for p in range(left, right + 1, step):
            if use_horizontal:
                out[fixed][p] = line_color
            else:
                out[p][fixed] = line_color

    return out
